const CACHE='spirit-house-v3';const ASSETS=["./", "index.html", "style.css", "app.js", "engine.js", "manifest.webmanifest", "icon.svg", "icon-192.png", "icon-512.png", "characters/Alex.webp", "characters/Billy.webp", "characters/Catherine.png", "characters/demarin.webp", "characters/elisa.webp", "characters/Eva.png", "characters/Evaggelia.png", "characters/evelyn.webp", "characters/hope.webp", "characters/irene.png", "characters/Jasmine.png", "characters/Luna.webp", "characters/pauline.webp", "characters/phillip.webp", "characters/rino.webp", "characters/sargenie.jpeg", "characters/smaragda.jpeg", "characters/Sorina.png", "characters/tony.webp", "characters/vicky.jpg", "characters/Violet.png", "characters/zoe.jpeg"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting()});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('spirit-house-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.match(e.request).then(cached=>cached||fetch(e.request)));});
